import { Vehicle } from "../../Models/vehicle.model.js";

export const addVehicle = async (req, res) => {
  try {
    const { name, brand, color, status, model, seat_no } = req.body;

    if (!name) {
      return res.status(404).json({
        message: "Enter Vehicle Name",
        success: false
      })
    } else if (!brand) {
      return res.status(404).json({
        message: "Enter Brand Name",
        success: false
      })
    } else if (!color) {
      return res.status(404).json({
        message: "Enter Color Name",
        success: false
      })
    } else if (!model) {
      return res.status(404).json({
        message: "Enter Model Name",
        success: false
      })
    } else if (!seat_no) {
      return res.status(404).json({
        message: "Enter Seat No.",
        success: false
      })
    }

    const data = { name, brand, color, status, model, seat_no };
    const response = new Vehicle(data);
    await response.save();
    res.status(200).json({
      message: "Vehicle added successfully",
      success: true,
      data: response
    });
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while adding vehicle",
      success: false
    })
  }
}






